  static Transform Model(Transform parent,string path,Vector3 position,Vector3 size){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(asset==null)throw new Exception("Missing owned asset "+path);var g=(GameObject)PrefabUtility.InstantiatePrefab(asset);PrefabUtility.UnpackPrefabInstance(g,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);g.name=Path.GetFileNameWithoutExtension(path);g.transform.SetParent(parent,false);foreach(var j in g.GetComponentsInChildren<Joint>(true))UnityEngine.Object.DestroyImmediate(j);foreach(var c in g.GetComponentsInChildren<Component>(true))if(c!=null&&!(c is Transform)&&!(c is Renderer)&&!(c is MeshFilter))UnityEngine.Object.DestroyImmediate(c);var renderers=g.GetComponentsInChildren<Renderer>();Bounds bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(size.x/bounds.size.x,size.y/bounds.size.y,size.z/bounds.size.z));bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);var meshes=new GameObject("Owned model meshes").transform;meshes.SetParent(g.transform,false);foreach(var child in g.transform.Cast<Transform>().ToArray())if(child!=meshes)child.SetParent(meshes,true);if(g.GetComponent<MeshFilter>()!=null){var part=new GameObject("Owned source mesh");part.transform.SetParent(meshes,false);part.AddComponent<MeshFilter>().sharedMesh=g.GetComponent<MeshFilter>().sharedMesh;part.AddComponent<MeshRenderer>().sharedMaterials=g.GetComponent<MeshRenderer>().sharedMaterials;UnityEngine.Object.DestroyImmediate(g.GetComponent<MeshRenderer>());UnityEngine.Object.DestroyImmediate(g.GetComponent<MeshFilter>());}var scale=g.transform.localScale;g.transform.localScale=Vector3.one;meshes.localScale=Vector3.Scale(meshes.localScale,scale);bounds=meshes.GetComponentsInChildren<Renderer>()[0].bounds;foreach(var r in meshes.GetComponentsInChildren<Renderer>())bounds.Encapsulate(r.bounds);meshes.position-=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);g.transform.position=position;return g.transform;}
  static GameObject MeshPart(string name,Transform parent,Vector3[] vertices,int[] triangles,Material material){var mesh=new Mesh{name=name};mesh.vertices=vertices;mesh.triangles=triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();string path=Root+"/Models/"+name+".asset";var stored=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(stored==null){AssetDatabase.CreateAsset(mesh,path);stored=mesh;}else UnityEngine.Object.DestroyImmediate(mesh);var g=new GameObject(name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=stored;g.AddComponent<MeshRenderer>().sharedMaterial=material;return g;}
  static void Canopy(Transform parent,Vector3 p,Material color){var root=new GameObject("Striped festival stall").transform;root.SetParent(parent);root.position=p;var roof=MeshPart("Festival canopy",root,new[]{new Vector3(-2,2.7f,-1.5f),new Vector3(0,3.5f,-1.5f),new Vector3(2,2.7f,-1.5f),new Vector3(-2,2.7f,1.5f),new Vector3(0,3.5f,1.5f),new Vector3(2,2.7f,1.5f)},new[]{0,1,3,1,4,3,1,2,4,2,5,4,3,1,0,3,4,1,4,2,1,4,5,2},color);foreach(float x in new[]{-1.8f,1.8f})foreach(float z in new[]{-1.3f,1.3f})SportsEventAuthoring.Box("Stall post",new Vector3(x,1.35f,z),new Vector3(.12f,2.7f,.12f),ivory,groundContact,root);SportsEventAuthoring.Box("Stall counter",new Vector3(0,.9f,.4f),new Vector3(3.5f,1.8f,1.4f),color,groundContact,root);}
  static void Fire(Vector3 position,float scale){var g=new GameObject("Bounded cartoon fire");g.transform.position=position;var ps=g.AddComponent<ParticleSystem>();ps.Stop();var main=ps.main;main.loop=true;main.startLifetime=new ParticleSystem.MinMaxCurve(.5f,1.5f);main.startSpeed=new ParticleSystem.MinMaxCurve(1,3);main.startSize=new ParticleSystem.MinMaxCurve(.4f*scale,1.2f*scale);main.startColor=new ParticleSystem.MinMaxGradient(new Color(1,.2f,.015f,.8f),new Color(1,.7f,.035f,.8f));main.maxParticles=40;var emission=ps.emission;emission.rateOverTime=18;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=12;shape.radius=scale*.5f;shape.rotation=new Vector3(-90,0,0);var renderer=ps.GetComponent<ParticleSystemRenderer>();var material=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Parade fire.mat");if(material==null){material=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));material.SetFloat("_Surface",1);material.SetFloat("_Blend",2);material.SetFloat("_SrcBlend",5);material.SetFloat("_DstBlend",1);material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");AssetDatabase.CreateAsset(material,Root+"/Materials/Parade fire.mat");}renderer.sharedMaterial=material;var color=ps.colorOverLifetime;color.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(new Color(1,.8f,.1f),0),new GradientColorKey(new Color(.8f,.1f,.01f),1)},new[]{new GradientAlphaKey(.8f,0),new GradientAlphaKey(0,1)});color.color=gradient;var smokeAsset=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NWH/Vehicle Physics 2/Effects/Prefabs/ExhaustSmoke.prefab");if(smokeAsset!=null){var smoke=UnityEngine.Object.Instantiate(smokeAsset,g.transform);smoke.transform.localPosition=Vector3.up*scale;smoke.transform.localRotation=Quaternion.Euler(-90,0,0);foreach(var p in smoke.GetComponentsInChildren<ParticleSystem>()){var s=p.main;s.maxParticles=35;s.startLifetime=3;s.startSize=scale*2;var e=p.emission;e.rateOverTime=6;}}}
  public static void BakeNavigation(NavMeshSurface surface){surface.RemoveData();var sources=new List<NavMeshBuildSource>();NavMeshBuilder.CollectSources(new Bounds(Vector3.zero,new Vector3(150,60,150)),1,NavMeshCollectGeometry.PhysicsColliders,0,new List<NavMeshBuildMarkup>(),sources);for(int i=0;i<sources.Count;i++){var source=sources[i];if(source.component!=null&&source.component.GetComponentInParent<NavMeshModifier>()!=null){source.area=1;sources[i]=source;}}var settings=NavMesh.GetSettingsByID(0);settings.agentRadius=1.8f;settings.agentHeight=2.3f;settings.agentClimb=.35f;settings.overrideVoxelSize=true;settings.voxelSize=.3f;var data=NavMeshBuilder.BuildNavMeshData(settings,sources,new Bounds(Vector3.zero,new Vector3(150,60,150)),Vector3.zero,Quaternion.identity);if(data==null)throw new Exception("Navigation bake failed");string path=Root+"/Models/City Navigation.asset";var old=AssetDatabase.LoadAssetAtPath<NavMeshData>(path);if(old!=null){EditorUtility.CopySerialized(data,old);UnityEngine.Object.DestroyImmediate(data);data=old;}else AssetDatabase.CreateAsset(data,path);surface.navMeshData=data;surface.AddData();}
