  public static PlowCharacter Character(PassengerProfile profile){
   string path=Root+"/Prefabs/"+profile.name+" Parade.prefab";var existing=AssetDatabase.LoadAssetAtPath<PlowPedestrian>(path);if(existing!=null)return new PlowCharacter{displayName=profile.passengerName,prefab=existing,reactions=profile.authoredDialogue,panicReaction="Look out! Truck!"};
