   var original=profile.modelPrefab!=null?profile.modelPrefab:AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LWS/TruckTaxi/Passengers/Prefabs/"+profile.name+".prefab");if(original==null)throw new Exception("Missing funny model "+profile.name);var funny=UnityEngine.Object.Instantiate(original);funny.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var filters=funny.GetComponentsInChildren<MeshFilter>(true);foreach(var f in filters){string n=f.name.ToLowerInvariant();string side=n.Contains("right")?"R":"L";string parent=n.Contains("foot")?"Bip01 "+side+" Foot":n.Contains("hand")?"Bip01 "+side+" Forearm":n.Contains("sleeve")?"Bip01 "+side+" UpperArm":n.Contains("pants")?"Bip01 Pelvis":n.Contains("body")||n.Contains("pouch")||n.Contains("crate")?"Bip01 Spine2":"Bip01 Head";var target=transforms.FirstOrDefault(t=>t.name==parent)??hips;f.transform.SetParent(target,true);}
