   ped.ragdoll=rig.AddComponent<TruckTaxiPedestrian>();ped.ragdoll.settings.minimumRagdollImpactSpeed=2;ped.ragdoll.settings.impactForceMultiplier=15;ped.ragdoll.settings.maximumRagdollImpulse=180;ped.ragdoll.settings.upwardImpulse=35;ped.ragdoll.settings.ragdollLifetime=24;
   var vest=GameObject.CreatePrimitive(PrimitiveType.Capsule);vest.name="Role vest · original character unchanged";UnityEngine.Object.DestroyImmediate(vest.GetComponent<Collider>());vest.transform.position=new Vector3(0,.73f,.015f);vest.transform.localScale=new Vector3(.77f,.3f,.49f);vest.transform.SetParent(bone("Bip01 Spine2"),true);ped.vest=vest.GetComponent<Renderer>();ped.vest.sharedMaterial=teal;
   ped.frontBadge=PlowBadgesAuthoring.Label("Front role badge","+10",new Vector3(0,.72f,.29f),.025f,Color.white);ped.frontBadge.transform.SetParent(vest.transform,true);ped.backBadge=PlowBadgesAuthoring.Label("Rear role badge","+10",new Vector3(0,.72f,-.29f),.025f,Color.white);ped.frontBadge.transform.rotation=Quaternion.Euler(0,180,0);ped.backBadge.transform.rotation=Quaternion.identity;ped.backBadge.transform.SetParent(vest.transform,true);ped.beacon=PlowBadgesAuthoring.Label("Overhead scoring symbol","+10",new Vector3(0,2.1f,0),.025f,Color.cyan);ped.beacon.transform.SetParent(rig.transform,true);
   foreach(var b in rig.GetComponentsInChildren<Rigidbody>())b.isKinematic=true;var cap=rig.GetComponent<CapsuleCollider>();cap.radius=.5f;cap.height=1.65f;cap.center=Vector3.up*.82f;
   var saved=PrefabUtility.SaveAsPrefabAsset(rig,path).GetComponent<PlowPedestrian>();UnityEngine.Object.DestroyImmediate(rig);return new PlowCharacter{displayName=string.IsNullOrEmpty(profile.passengerName)?profile.name:profile.passengerName,prefab=saved,reactions=profile.authoredDialogue,panicReaction="Heads up! Truck!"};
  }
  [MenuItem("Truck Sports/Pedestrian Plowing/Select Crowd Settings")]
  public static void SelectSettings(){Selection.activeObject=AssetDatabase.LoadAssetAtPath<PlowSettings>(SettingsPath);EditorGUIUtility.PingObject(Selection.activeObject);}
  [MenuItem("Truck Sports/Pedestrian Plowing/Add Selected Taxi Profiles to Crowd")]
  public static void AddSelectedProfiles(){var settings=AssetDatabase.LoadAssetAtPath<PlowSettings>(SettingsPath);teal=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Materials/Festival teal.mat");var entries=settings.characters.ToList();foreach(var p in Selection.objects.OfType<PassengerProfile>()){var entry=Character(p);if(!entries.Any(e=>e.prefab==entry.prefab))entries.Add(entry);}settings.characters=entries.ToArray();EditorUtility.SetDirty(settings);AssetDatabase.SaveAssets();Selection.activeObject=settings;}
  public static void Validate(){var scene=EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<PlowMatch>();if(m==null||m.trucks.Length!=8||m.spawnZones.Length<8||(m.crowdSettings.characters.Length==0||m.crowdSettings.characters.All(c=>c==null||c.prefab==null||c.weight<=0))||m.feedback.clips.Any(c=>c==null))throw new Exception("Plowing references incomplete");foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Missing Plowing script "+t.name);if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Plowing listener count");Debug.Log("PLOW_SAVED_SCENE_VALIDATED");}
 }
